/**
 * Errors that can occur across the ClipBridge FFI boundary.
 */
sealed class FfiException: kotlin.Exception() {
    
    class Crypto(
        
        val `msg`: kotlin.String
        ) : FfiException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Decode(
        
        val `msg`: kotlin.String
        ) : FfiException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class PayloadTooLarge(
        
        val `size`: kotlin.ULong, 
        
        val `max`: kotlin.ULong
        ) : FfiException() {
        override val message
            get() = "size=${ `size` }, max=${ `max` }"
    }
    
    class GroupMismatch(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class HashMismatch(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class Storage(
        
        val `msg`: kotlin.String
        ) : FfiException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Image(
        
        val `msg`: kotlin.String
        ) : FfiException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class InvalidPairingUri(
        
        val `msg`: kotlin.String
        ) : FfiException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Relay(
        
        val `msg`: kotlin.String
        ) : FfiException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Io(
        
        val `msg`: kotlin.String
        ) : FfiException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Serialization(
        
        val `msg`: kotlin.String
        ) : FfiException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Generic(
        
        val `msg`: kotlin.String
        ) : FfiException() {
        override val message
            get() = "msg=${ `msg` }"
