/**
 * Events delivered by the WebSocket relay hub.
 */
sealed class FfiRelayEvent: Disposable  {
    
    data class Deliver(
        val `envelope`: uniffi.clip_ffi.FfiEnvelope) : FfiRelayEvent()
        
    {
        

        companion object
    }
    
    data class Ack(
        val `id`: kotlin.String) : FfiRelayEvent()
        
    {
        

        companion object
    }
    
    data class Error(
        val `code`: kotlin.String, 
        val `message`: kotlin.String, 
        val `id`: kotlin.String?) : FfiRelayEvent()
        
    {
        

        companion object
    }
    

    
    @Suppress("UNNECESSARY_SAFE_CALL") // codegen is much simpler if we unconditionally emit safe calls here
    override fun destroy() {
        when(this) {
            is FfiRelayEvent.Deliver -> {
                
    Disposable.destroy(
        this.`envelope`
    )
                
            }
            is FfiRelayEvent.Ack -> {
                
    Disposable.destroy(
        this.`id`
    )
                
            }
            is FfiRelayEvent.Error -> {
                
    Disposable.destroy(
        this.`code`,
        this.`message`,
        this.`id`
    )
                
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
    

    
    


    companion object
}

